contracts/pendle-pt-fixed-rate-vault/int.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import {
    TokenInput,
    TokenOutput,
    ApproxParams,
    LimitOrderData
} from "@pendle/core-v2/contracts/interfaces/IPAllActionTypeV3.sol";

/**
 * @title IPendlePTVaultAdapter
 * @author Venus
 * @notice Interface for the PendlePTVaultAdapter contract.
 * @dev Universal adapter that wraps Pendle PT swap and Venus Core deposit/redeem into single
 *      transactions. Users deposit tokens (e.g. USDC, BNB) and receive Venus vTokens.
 *      A single adapter handles all PT markets via an internal market registry.
 *      The adapter does NOT hold user funds or track user positions — all user accounting is
 *      managed by Venus vTokens. The contract should hold zero token balances between transactions.
 */
interface IPendlePTVaultAdapter {
    // ═══════════════════════════════════════════════════════════════════════
    //                              STRUCTS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Configuration for a registered Pendle PT market.
     * @param pt Principal Token address
     * @param sy Standardized Yield token address
     * @param yt Yield Token address (needed for maturity redemption)
     * @param vToken Venus VToken market address for this PT
     * @param maturity PT expiry timestamp (Unix timestamp)
     */
    struct MarketConfig {
        address pt;
        address sy;
        address yt;
        address vToken;
        uint256 maturity;
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                              EVENTS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Emitted when a new PT market is registered in the adapter.
     * @param pendleMarket Pendle market address that was registered
     * @param pt Principal Token address
     * @param vToken Venus VToken market address
     * @param maturity PT maturity timestamp
     */
    event MarketAdded(address indexed pendleMarket, address indexed pt, address indexed vToken, uint256 maturity);

    /**
     * @notice Emitted when a user deposits tokens and receives vTokens.
     * @param pendleMarket Pendle market address used for the deposit
     * @param user Address of the user who deposited
     * @param tokenIn The input token address deposited by the user
     * @param amountIn Amount of input tokens deposited
     * @param ptAmount Amount of PT tokens received from Pendle swap
     * @param vTokenAmount Amount of vTokens minted to the user
     */
    event Deposited(
        address indexed pendleMarket,
        address indexed user,
        address indexed tokenIn,
        uint256 amountIn,
        uint256 ptAmount,
        uint256 vTokenAmount
    );

    /**
     * @notice Emitted when a user withdraws (before maturity) by selling PT on Pendle AMM.
     * @param pendleMarket Pendle market address used for the withdrawal
     * @param user Address of the user who withdrew
     * @param tokenOut The output token address received by the user
     * @param vTokenAmount Amount of vTokens redeemed
     * @param ptAmount Amount of PT tokens sold on Pendle
     * @param amountOut Amount of output tokens received by user
     */
    event Withdrawn(
        address indexed pendleMarket,
        address indexed user,
        address indexed tokenOut,
        uint256 vTokenAmount,
        uint256 ptAmount,
        uint256 amountOut
    );

    /**
     * @notice Emitted when a user redeems at or after maturity (1:1 redemption via SY).
     * @param pendleMarket Pendle market address used for the redemption
     * @param user Address of the user who redeemed
     * @param tokenOut The output token address received by the user
     * @param vTokenAmount Amount of vTokens redeemed
     * @param ptAmount Amount of PT tokens redeemed
     * @param amountOut Amount of output tokens received by user
     */
    event RedeemedAtMaturity(
        address indexed pendleMarket,
        address indexed user,
        address indexed tokenOut,
        uint256 vTokenAmount,
        uint256 ptAmount,
        uint256 amountOut
    );

    /**
     * @notice Emitted when the owner sweeps ERC-20 tokens from the contract.
     * @param token The ERC-20 token address swept
     * @param to The recipient address
     * @param amount Amount of tokens swept
     */
    event SweepTokens(address indexed token, address indexed to, uint256 amount);

    /**
     * @notice Emitted when the owner sweeps native BNB from the contract.
     * @param to The recipient address
     * @param amount Amount of native BNB swept
     */
    event SweepNative(address indexed to, uint256 amount);

    // ═══════════════════════════════════════════════════════════════════════
    //                           CUSTOM ERRORS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Error thrown when a zero amount is provided as input.
    error ZeroAmount();

    /// @notice Error thrown when a zero address is provided where a valid address is required.
    error ZeroAddress();

    /**
     * @notice Error thrown when attempting to interact with a market that has not been registered.
     * @param pendleMarket The Pendle market address that is not registered
     */
    error MarketNotRegistered(address pendleMarket);

    /**
     * @notice Error thrown when attempting to register a market that is already registered.
     * @param pendleMarket The Pendle market address that is already registered
     */
    error MarketAlreadyRegistered(address pendleMarket);

    /**
     * @notice Error thrown when attempting an operation that requires the market to be matured but it hasn't matured yet.
     * @param maturity The maturity timestamp of the PT
     * @param currentTime The current block timestamp
     */
    error MarketNotMatured(uint256 maturity, uint256 currentTime);

    /**
     * @notice Error thrown when attempting a pre-maturity operation on a market that has already matured.
     * @param maturity The maturity timestamp of the PT
     * @param currentTime The current block timestamp
     */
    error MarketAlreadyMatured(uint256 maturity, uint256 currentTime);

    /// @notice Error thrown when the TokenInput tokenIn is the zero address.
    error InvalidTokenInput();

    /**
     * @notice Error thrown when the actual amount received does not match the expected input amount.
     * @param expected The expected amount (input.netTokenIn from calldata)
     * @param received The actual amount received (token balance delta or msg.value)
     */
    error InputAmountMismatch(uint256 expected, uint256 received);

    /**
     * @notice Error thrown when Venus VToken mint operation fails.
     * @param errorCode The error code returned by the VToken contract
     */
    error VTokenMintFailed(uint256 errorCode);

    /// @notice Error thrown when a mint operation succeeds but produces zero vTokens (dust input).
    error ZeroVTokensMinted();

    /**
     * @notice Error thrown when Venus VToken redeem operation fails.
     * @param errorCode The error code returned by the VToken contract
     */
    error VTokenRedeemFailed(uint256 errorCode);

    /**
     * @notice Error thrown when the vToken's underlying asset does not match the derived PT address.
     * @param vToken The vToken address whose underlying was checked
     * @param expectedUnderlying The expected underlying (PT) address
     */
    error UnderlyingMismatch(address vToken, address expectedUnderlying);

    /**
     * @notice Error thrown when the vToken is not listed in the Comptroller.
     * @param vToken The vToken address that is not listed
     */
    error VTokenNotListed(address vToken);

    // ═══════════════════════════════════════════════════════════════════════
    //                          CORE — DEPOSIT
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Deposit tokenIn → swap to PT via Pendle → deposit PT into Venus → user receives vTokens.
     * @dev User must approve this adapter for `input.netTokenIn` of tokenIn beforehand.
     *      The contract will be paused during emergency situations.
     *      Accepts any token from Pendle's tokensIn array for the given market.
     *      No beforeMaturity check — Pendle Router naturally reverts post-maturity swaps.
     * @param pendleMarket Pendle market address identifying the PT market
     * @param minPtOut Minimum PT to receive from Pendle swap (slippage protection)
     * @param guessPtOut Off-chain binary search hint from the Pendle API (saves ~180k gas)
     * @param input Token routing configuration from the Pendle API (includes tokenIn and netTokenIn)
     * @param limit Limit order fill data (can be empty struct for simple swaps)
     * @return netVTokensMinted Amount of vTokens credited to the user
     */
    function deposit(
        address pendleMarket,
        uint256 minPtOut,
        ApproxParams calldata guessPtOut,
        TokenInput calldata input,
        LimitOrderData calldata limit
    ) external returns (uint256 netVTokensMinted);

    /**
     * @notice Deposit native BNB → swap to PT via Pendle Router → deposit PT into Venus → user receives vTokens.
     * @dev Passes native BNB directly to Pendle Router (payable) without wrapping to WBNB.
     *      Any excess native BNB is refunded to the user.
     *      No beforeMaturity check — Pendle Router naturally reverts post-maturity swaps.
     * @param pendleMarket Pendle market address identifying the PT market
     * @param minPtOut Minimum PT to receive from Pendle swap (slippage protection)
     * @param guessPtOut Off-chain binary search hint from the Pendle API
     * @param input Token routing configuration from the Pendle API
     * @param limit Limit order fill data (can be empty struct)
     * @return netVTokensMinted Amount of vTokens credited to the user
     */
    function depositNative(
        address pendleMarket,
        uint256 minPtOut,
        ApproxParams calldata guessPtOut,
        TokenInput calldata input,
        LimitOrderData calldata limit
    ) external payable returns (uint256 netVTokensMinted);

    // ═══════════════════════════════════════════════════════════════════════
    //                      CORE — WITHDRAW & REDEEM
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Withdraw before maturity: redeem vTokens → sell PT on Pendle AMM → user receives tokenOut.
     * @dev Reverts after maturity — use redeemAtMaturity instead for post-maturity withdrawals.
     *      Supports both ERC-20 and native token (address(0)) output via Pendle Router.
     *      User must have delegated to this adapter in the Comptroller beforehand.
     *      PT is sold on the Pendle AMM at current market price (subject to slippage).
     * @param pendleMarket Pendle market address
     * @param vTokenAmount Amount of vTokens to redeem
     * @param output Token routing configuration from the Pendle API
     * @param limit Limit order fill data (can be empty struct)
     * @return netTokenOut Amount of output tokens received by the user
     */
    function withdraw(
        address pendleMarket,
        uint256 vTokenAmount,
        TokenOutput calldata output,
        LimitOrderData calldata limit
    ) external returns (uint256 netTokenOut);

    /**
     * @notice Redeem at or after maturity: redeem vTokens → redeem PT 1:1 via SY → user receives tokenOut.
     * @dev No AMM swap — PT is redeemed directly through SY at 1:1 ratio (no price impact).
     *      Supports both ERC-20 and native token (address(0)) output via Pendle Router.
     *      User must have delegated to this adapter in the Comptroller beforehand.
     * @param pendleMarket Pendle market address
     * @param vTokenAmount Amount of vTokens to redeem
     * @param output Token routing configuration from the Pendle API
     * @return netTokenOut Amount of output tokens received by the user
     */
    function redeemAtMaturity(
        address pendleMarket,
        uint256 vTokenAmount,
        TokenOutput calldata output
    ) external returns (uint256 netTokenOut);

    // ═══════════════════════════════════════════════════════════════════════
    //                          ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Register a new PT market. Derives PT, SY, YT, and maturity from on-chain data.
     * @dev Access controlled via AccessControlManager.
     *      Reads token addresses and maturity from the Pendle market contract.
     *      Validates that the vToken's underlying matches the derived PT address.
     * @param pendleMarket Pendle AMM market address to register
     * @param vToken Venus VToken market address for this PT
     */
    function addMarket(address pendleMarket, address vToken) external;

    /**
     * @notice Pause all deposit/withdraw operations (emergency).
     * @dev Access controlled via AccessControlManager.
     *      When paused, all user-facing functions revert.
     */
    function pause() external;

    /**
     * @notice Unpause operations.
     * @dev Access controlled via AccessControlManager.
     */
    function unpause() external;

    /**
     * @notice Recover ERC-20 tokens accidentally sent to the contract.
     * @dev Only callable by the contract owner.
     *      Should only be used for recovering mistakenly sent tokens.
     *      The contract should hold zero balances during normal operations.
     * @param token ERC-20 token address to sweep
     * @param to Recipient address
     * @param amount Amount to transfer
     */
    function sweepTokens(address token, address to, uint256 amount) external;

    /**
     * @notice Recover native BNB accidentally sent to the contract.
     * @dev Only callable by the contract owner.
     *      The receive() function is open for Pendle Router refunds, so native BNB
     *      can accumulate from accidental transfers or selfdestruct.
     * @param to Recipient address
     * @param amount Amount of native BNB to transfer
     */
    function sweepNative(address payable to, uint256 amount) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                          VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Get the number of registered markets.
     * @return Total count of markets registered in the adapter
     */
    function getMarketCount() external view returns (uint256);

    /**
     * @notice Get all registered market addresses.
     * @dev The list grows unboundedly — expected to remain small in practice.
     * @return Array of all registered Pendle market addresses
     */
    function getAllMarkets() external view returns (address[] memory);

    /**
     * @notice Check if a specific registered PT market has matured.
     * @param pendleMarket Pendle market address
     * @return True if the current timestamp is at or past the market's maturity
     */
    function isMatured(address pendleMarket) external view returns (bool);

    /**
     * @notice Check if a user has delegated to this adapter in the Comptroller.
     * @dev Delegation is required for withdraw/redeemAtMaturity (redeemBehalf).
     *      Users must call Comptroller.updateDelegate(adapter, true) before withdrawing.
     * @param user User address to check
     * @return True if the user has approved this adapter as a delegate
     */
    function isDelegated(address user) external view returns (bool);

    /**
     * @notice Get the immutable Pendle Router address.
     * @return Pendle Router address used for all PT swaps and redemptions
     */
    function PENDLE_ROUTER() external view returns (address);

    /**
     * @notice Get the immutable Venus Comptroller address.
     * @return Venus core pool Comptroller address
     */
    function COMPTROLLER() external view returns (address);
}

// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

/// @title Venus Comptroller Interface for PendlePTVaultAdapter
/// @author Venus
/// @notice Minimal Comptroller interface covering delegation checks.
interface IVenusComptroller {
    /// @notice Check if `delegate` is approved to act on behalf of `user`.
    /// @param user The account that granted delegation.
    /// @param delegate The account that was granted delegation.
    /// @return True if `delegate` is approved.
    function approvedDelegates(address user, address delegate) external view returns (bool);

    /// @notice Checks whether the given vToken market is listed in the Comptroller.
    /// @param vToken The vToken address to check.
    /// @return True if the market is listed.
    function isMarketListed(address vToken) external view returns (bool);
}

// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

/// @title Venus VToken Interface for PendlePTVaultAdapter
/// @author Venus Protocol
/// @notice Minimal VToken interface covering mintBehalf/redeemBehalf operations.
/// @dev Both functions return 0 on success and a non-zero error code on failure (Compound pattern).
interface IVenusVToken {
    /// @notice Deposit underlying tokens and mint vTokens to `receiver`.
    /// @param receiver Address that receives the minted vTokens.
    /// @param mintAmount Amount of underlying tokens to deposit.
    /// @return 0 on success, non-zero error code on failure.
    function mintBehalf(address receiver, uint256 mintAmount) external returns (uint256);

    /// @notice Burn vTokens belonging to `owner` and send underlying tokens to caller (msg.sender).
    /// @dev Requires the caller to be an approved delegate of `owner` in the Comptroller.
    /// @param owner Address whose vTokens are redeemed.
    /// @param redeemTokens Amount of vTokens to burn.
    /// @return 0 on success, non-zero error code on failure.
    function redeemBehalf(address owner, uint256 redeemTokens) external returns (uint256);

    /// @notice Returns the underlying asset address of this vToken market.
    /// @return Address of the underlying token
    function underlying() external view returns (address);

    /// @notice Returns the Comptroller address associated with this vToken market.
    /// @return Address of the Comptroller contract for delegation checks.
    function comptroller() external view returns (address);

    /// @notice Returns the vToken balance of `account`.
    /// @param account The address to query the balance of.
    /// @return The amount of vTokens held by `account`.
    function balanceOf(address account) external view returns (uint256);
}

contracts/pendle-pt-fixed-rate-vault/Pen.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { PausableUpgradeable } from "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Address } from "@openzeppelin/contracts/utils/Address.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";

import { IPAllActionV3 } from "@pendle/core-v2/contracts/interfaces/IPAllActionV3.sol";
import {
    TokenInput,
    TokenOutput,
    ApproxParams,
    LimitOrderData
} from "@pendle/core-v2/contracts/interfaces/IPAllActionTypeV3.sol";
import {
    IPMarket,
    IStandardizedYield,
    IPPrincipalToken,
    IPYieldToken
} from "@pendle/core-v2/contracts/interfaces/IPMarket.sol";
import { IVenusVToken } from "./interfaces/IVenusVToken.sol";
import { IVenusComptroller } from "./interfaces/IVenusComptroller.sol";
import { IPendlePTVaultAdapter } from "./interfaces/IPendlePTVaultAdapter.sol";

/**
 * @title PendlePTVaultAdapter
 * @author Venus
 * @notice Universal adapter that wraps Pendle PT swap and Venus Core deposit/redeem into single transactions.
 */
contract PendlePTVaultAdapter is
    IPendlePTVaultAdapter,
    AccessControlledV8,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════════════════
    //                            IMMUTABLES
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Pendle Router address (IPAllActionV3).
    address public immutable PENDLE_ROUTER;

    /// @notice Venus core pool Comptroller address.
    address public immutable COMPTROLLER;

    // ═══════════════════════════════════════════════════════════════════════
    //                          STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Pendle market address → full market configuration.
    mapping(address => MarketConfig) public markets;

    /// @notice Ordered list of all registered market addresses (for enumeration).
    /// @dev Grows unboundedly — expected to remain small.
    ///      Matured markets remain in the list to allow late redemptions.
    address[] public marketList;

    /// @dev Reserved storage gap for future upgrades.
    uint256[48] private __gap;

    // ═══════════════════════════════════════════════════════════════════════
    //                             MODIFIERS
    // ═══════════════════════════════════════════════════════════════════════

    /// @dev Reverts if the market is not registered.
    modifier onlyRegisteredMarket(address pendleMarket) {
        _requireRegisteredMarket(pendleMarket);
        _;
    }

    /// @dev Reverts if the market has not yet matured (block.timestamp < maturity).
    modifier atOrAfterMaturity(address pendleMarket) {
        uint256 mat = markets[pendleMarket].maturity;
        if (block.timestamp < mat) revert MarketNotMatured(mat, block.timestamp);
        _;
    }

    /// @dev Reverts if the market has already matured (block.timestamp >= maturity).
    modifier beforeMaturity(address pendleMarket) {
        uint256 maturity = markets[pendleMarket].maturity;
        if (!(block.timestamp < maturity)) revert MarketAlreadyMatured(maturity, block.timestamp);
        _;
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                            CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════

    /// @param pendleRouter_ Pendle Router (IPAllActionV3) address.
    /// @param comptroller_ Venus core pool Comptroller address.
    constructor(address pendleRouter_, address comptroller_) {
        if (pendleRouter_ == address(0)) revert ZeroAddress();
        if (comptroller_ == address(0)) revert ZeroAddress();
        PENDLE_ROUTER = pendleRouter_;
        COMPTROLLER = comptroller_;

        _disableInitializers();
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                          RECEIVE FUNCTION
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Accept native BNB (required for Pendle Router refunds during depositNative).
    receive() external payable {}

    // ═══════════════════════════════════════════════════════════════════════
    //                           INITIALIZER
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Initializes the proxy state. Called once after proxy deployment.
    /// @param accessControlManager_ Address of the Venus AccessControlManager contract.
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
        __Pausable_init();
        __ReentrancyGuard_init();
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                          CORE — DEPOSIT
    // ═══════════════════════════════════════════════════════════════════════

    // Note: deposit and depositNative have no beforeMaturity check —
    // Pendle Router naturally reverts post-maturity swaps.

    /// @inheritdoc IPendlePTVaultAdapter
    function deposit(
        address pendleMarket,
        uint256 minPtOut,
        ApproxParams calldata guessPtOut,
        TokenInput calldata input,
        LimitOrderData calldata limit
    ) external whenNotPaused nonReentrant onlyRegisteredMarket(pendleMarket) returns (uint256 netVTokensMinted) {
        if (input.netTokenIn == 0) revert ZeroAmount();
        if (input.tokenIn == address(0)) revert InvalidTokenInput();

        uint256 netPtOut;
        {
            MarketConfig storage config = markets[pendleMarket];
            address pt = config.pt;
            address vToken = config.vToken;
            uint256 ptBalanceBefore = IERC20(pt).balanceOf(address(this));
            uint256 syBalanceBefore = IERC20(config.sy).balanceOf(address(this));

            // 1. Pull tokens from user → adapter (accepts any token from Pendle's tokensIn)
            uint256 balanceBefore = IERC20(input.tokenIn).balanceOf(address(this));
            IERC20(input.tokenIn).safeTransferFrom(msg.sender, address(this), input.netTokenIn);
            uint256 received = IERC20(input.tokenIn).balanceOf(address(this)) - balanceBefore;

            // Validate actual received amount matches Pendle's expected input
            if (input.netTokenIn != received) revert InputAmountMismatch(input.netTokenIn, received);

            // 2. Swap tokenIn → PT via Pendle Router (Pendle handles aggregator routing if needed)
            //    Use balance delta instead of return value to prevent inflation via malicious limitRouter
            _swapToPt(pendleMarket, minPtOut, guessPtOut, input, limit);
            netPtOut = IERC20(pt).balanceOf(address(this)) - ptBalanceBefore;

            // 3. Deposit PT into Venus — vTokens go to user
            netVTokensMinted = _mintVTokens(pt, vToken, netPtOut);

            // 4. Safety sweep: return residual tokens to user — SY dust can occur when
            //    limit orders trigger Pendle's epsSkipMarket threshold
            _sweepDust(pt, msg.sender, ptBalanceBefore);
            _sweepDust(config.sy, msg.sender, syBalanceBefore);
            _sweepDust(input.tokenIn, msg.sender, balanceBefore);
        }

        emit Deposited(pendleMarket, msg.sender, input.tokenIn, input.netTokenIn, netPtOut, netVTokensMinted);
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function depositNative(
        address pendleMarket,
        uint256 minPtOut,
        ApproxParams calldata guessPtOut,
        TokenInput calldata input,
        LimitOrderData calldata limit
    )
        external
        payable
        whenNotPaused
        nonReentrant
        onlyRegisteredMarket(pendleMarket)
        returns (uint256 netVTokensMinted)
    {
        if (msg.value == 0) revert ZeroAmount();
        if (input.tokenIn != address(0)) revert InvalidTokenInput();

        MarketConfig storage config = markets[pendleMarket];
        address pt = config.pt;
        address vToken = config.vToken;
        uint256 ptBalanceBefore = IERC20(pt).balanceOf(address(this));
        uint256 syBalanceBefore = IERC20(config.sy).balanceOf(address(this));
        uint256 nativeBalanceBefore = address(this).balance - msg.value;

        // Validate calldata consistency
        if (input.netTokenIn != msg.value) revert InputAmountMismatch(input.netTokenIn, msg.value);

        // 1. Swap native BNB → PT via Pendle Router
        //    Use balance delta instead of return value to prevent inflation via malicious limitRouter
        _swapToPtNative(pendleMarket, minPtOut, guessPtOut, input, limit);
        uint256 netPtOut = IERC20(pt).balanceOf(address(this)) - ptBalanceBefore;

        // 2. Deposit PT into Venus — vTokens go to user
        netVTokensMinted = _mintVTokens(pt, vToken, netPtOut);

        // 3. Safety sweep: return residual tokens to user — SY dust can occur when
        //    limit orders trigger Pendle's epsSkipMarket threshold
        _sweepDust(pt, msg.sender, ptBalanceBefore);
        _sweepDust(config.sy, msg.sender, syBalanceBefore);

        // 4. Refund any native BNB returned to the adapter during the swap
        _refundNativeDust(nativeBalanceBefore);

        emit Deposited(pendleMarket, msg.sender, input.tokenIn, msg.value, netPtOut, netVTokensMinted);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                      CORE — WITHDRAW & REDEEM
    // ═══════════════════════════════════════════════════════════════════════

    /// @inheritdoc IPendlePTVaultAdapter
    function withdraw(
        address pendleMarket,
        uint256 vTokenAmount,
        TokenOutput calldata output,
        LimitOrderData calldata limit
    )
        external
        whenNotPaused
        nonReentrant
        onlyRegisteredMarket(pendleMarket)
        beforeMaturity(pendleMarket)
        returns (uint256 netTokenOut)
    {
        if (vTokenAmount == 0) revert ZeroAmount();

        MarketConfig storage config = markets[pendleMarket];
        address pt = config.pt;
        address vToken = config.vToken;

        // 1. Redeem vTokens → adapter receives PT
        uint256 ptBefore = IERC20(pt).balanceOf(address(this));
        _redeemVTokens(vToken, vTokenAmount);
        uint256 ptReceived = IERC20(pt).balanceOf(address(this)) - ptBefore;

        // 2. Swap PT → tokenOut via Pendle (sent directly to user, Pendle handles routing)
        netTokenOut = _swapPtToToken(pt, pendleMarket, ptReceived, output, limit);

        // 3. Safety sweep: not expected with exact-in swap, but guards against
        //    unexpected Router behavior leaving residual PT in the adapter
        _sweepDust(pt, msg.sender, ptBefore);

        emit Withdrawn(pendleMarket, msg.sender, output.tokenOut, vTokenAmount, ptReceived, netTokenOut);
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function redeemAtMaturity(
        address pendleMarket,
        uint256 vTokenAmount,
        TokenOutput calldata output
    )
        external
        whenNotPaused
        nonReentrant
        onlyRegisteredMarket(pendleMarket)
        atOrAfterMaturity(pendleMarket)
        returns (uint256 netTokenOut)
    {
        if (vTokenAmount == 0) revert ZeroAmount();

        MarketConfig storage config = markets[pendleMarket];
        address pt = config.pt;
        address vToken = config.vToken;
        address yt = config.yt;

        // 1. Redeem vTokens → adapter receives PT
        uint256 ptBefore = IERC20(pt).balanceOf(address(this));
        _redeemVTokens(vToken, vTokenAmount);
        uint256 ptReceived = IERC20(pt).balanceOf(address(this)) - ptBefore;

        // 2. Redeem PT 1:1 → tokenOut via Pendle (sent directly to user, Pendle handles routing)
        netTokenOut = _redeemPtToToken(pt, yt, ptReceived, output);

        // 3. Safety sweep: not expected with exact-in redemption, but guards against
        //    unexpected Router behavior leaving residual PT in the adapter
        _sweepDust(pt, msg.sender, ptBefore);

        emit RedeemedAtMaturity(pendleMarket, msg.sender, output.tokenOut, vTokenAmount, ptReceived, netTokenOut);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                          ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /// @inheritdoc IPendlePTVaultAdapter
    function addMarket(address pendleMarket, address vToken) external {
        _checkAccessAllowed("addMarket(address,address)");
        if (pendleMarket == address(0)) revert ZeroAddress();
        if (vToken == address(0)) revert ZeroAddress();
        if (markets[pendleMarket].pt != address(0)) revert MarketAlreadyRegistered(pendleMarket);

        // Validate that the vToken is listed in the Comptroller
        if (!IVenusComptroller(COMPTROLLER).isMarketListed(vToken)) revert VTokenNotListed(vToken);

        // Derive token addresses and maturity from Pendle market contract
        // solhint-disable-next-line var-name-mixedcase
        (IStandardizedYield _SY, IPPrincipalToken _PT, IPYieldToken _YT) = IPMarket(pendleMarket).readTokens();

        // Validate that the vToken's underlying matches the derived PT
        if (IVenusVToken(vToken).underlying() != address(_PT)) revert UnderlyingMismatch(vToken, address(_PT));

        uint256 maturity = IPMarket(pendleMarket).expiry();
        if (!(block.timestamp < maturity)) revert MarketAlreadyMatured(maturity, block.timestamp);

        markets[pendleMarket] = MarketConfig({
            pt: address(_PT),
            sy: address(_SY),
            yt: address(_YT),
            vToken: vToken,
            maturity: maturity
        });

        marketList.push(pendleMarket);

        emit MarketAdded(pendleMarket, address(_PT), vToken, maturity);
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function pause() external {
        _checkAccessAllowed("pause()");
        _pause();
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function unpause() external {
        _checkAccessAllowed("unpause()");
        _unpause();
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function sweepTokens(address token, address to, uint256 amount) external onlyOwner {
        if (token == address(0)) revert ZeroAddress();
        if (to == address(0)) revert ZeroAddress();
        IERC20(token).safeTransfer(to, amount);
        emit SweepTokens(token, to, amount);
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function sweepNative(address payable to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        Address.sendValue(to, amount);
        emit SweepNative(to, amount);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                          VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /// @inheritdoc IPendlePTVaultAdapter
    function getMarketCount() external view returns (uint256) {
        return marketList.length;
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function getAllMarkets() external view returns (address[] memory) {
        return marketList;
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function isMatured(address pendleMarket) external view returns (bool) {
        if (markets[pendleMarket].pt == address(0)) revert MarketNotRegistered(pendleMarket);
        return !(block.timestamp < markets[pendleMarket].maturity);
    }

    /// @inheritdoc IPendlePTVaultAdapter
    function isDelegated(address user) external view returns (bool) {
        return IVenusComptroller(COMPTROLLER).approvedDelegates(user, address(this));
    }

    // ═══════════════════════════════════════════════════════════════════════
    //                        INTERNAL HELPERS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Swaps tokenIn to PT via Pendle Router.
     * @param pendleMarket The Pendle market address for the swap.
     * @param minPtOut Minimum PT to receive (slippage protection).
     * @param guessPtOut Off-chain binary search approximation parameters.
     * @param input Token input configuration from Pendle API (contains tokenIn address).
     * @param limit Limit order fill data.
     * @dev Approves router, performs swap, then resets approval to zero.
     *      Return value is intentionally discarded — callers use balance delta
     *      to prevent inflation via malicious limitRouter.
     */
    function _swapToPt(
        address pendleMarket,
        uint256 minPtOut,
        ApproxParams calldata guessPtOut,
        TokenInput calldata input,
        LimitOrderData calldata limit
    ) internal {
        IERC20(input.tokenIn).forceApprove(PENDLE_ROUTER, input.netTokenIn);

        IPAllActionV3(PENDLE_ROUTER).swapExactTokenForPt(
            address(this), // PT receiver = adapter (so we can deposit into Venus)
            pendleMarket,
            minPtOut,
            guessPtOut,
            input,
            limit
        );

        IERC20(input.tokenIn).forceApprove(PENDLE_ROUTER, 0);
    }

    /**
     * @notice Swaps native BNB to PT via Pendle Router.
     * @param pendleMarket The Pendle market address for the swap.
     * @param minPtOut Minimum PT to receive (slippage protection).
     * @param guessPtOut Off-chain binary search approximation parameters.
     * @param input Token input configuration from Pendle API.
     * @param limit Limit order fill data.
     * @dev Separated from _swapToPt to avoid stack-too-deep in depositNative.
     *      Return value is intentionally discarded — callers use balance delta
     *      to prevent inflation via malicious limitRouter.
     */
    function _swapToPtNative(
        address pendleMarket,
        uint256 minPtOut,
        ApproxParams calldata guessPtOut,
        TokenInput calldata input,
        LimitOrderData calldata limit
    ) internal {
        IPAllActionV3(PENDLE_ROUTER).swapExactTokenForPt{ value: msg.value }(
            address(this),
            pendleMarket,
            minPtOut,
            guessPtOut,
            input,
            limit
        );
    }

    /**
     * @notice Deposits PT into Venus and mints vTokens on behalf of the caller.
     * @param pt The PT token address to deposit.
     * @param vToken The Venus vToken address to mint into.
     * @param ptAmount Amount of PT tokens to deposit.
     * @return netVTokensMinted Amount of vTokens minted to msg.sender.
     * @dev Approves vToken, calls mintBehalf, then resets approval to zero.
     *      Reverts with VTokenMintFailed if the mint operation returns non-zero error.
     */
    function _mintVTokens(address pt, address vToken, uint256 ptAmount) internal returns (uint256 netVTokensMinted) {
        uint256 vTokenBalanceBefore = IVenusVToken(vToken).balanceOf(msg.sender);

        IERC20(pt).forceApprove(vToken, ptAmount);
        uint256 mintErr = IVenusVToken(vToken).mintBehalf(msg.sender, ptAmount);
        if (mintErr != 0) revert VTokenMintFailed(mintErr);

        netVTokensMinted = IVenusVToken(vToken).balanceOf(msg.sender) - vTokenBalanceBefore;
        if (netVTokensMinted == 0) revert ZeroVTokensMinted();

        IERC20(pt).forceApprove(vToken, 0);
    }

    /**
     * @notice Redeems vTokens from Venus on behalf of the caller.
     * @param vToken The Venus vToken address to redeem from.
     * @param vTokenAmount Amount of vTokens to redeem.
     * @dev Underlying PT tokens are sent to this adapter contract.
     *      Reverts with VTokenRedeemFailed if the redeem operation returns non-zero error.
     */
    function _redeemVTokens(address vToken, uint256 vTokenAmount) internal {
        uint256 redeemErr = IVenusVToken(vToken).redeemBehalf(msg.sender, vTokenAmount);
        if (redeemErr != 0) revert VTokenRedeemFailed(redeemErr);
    }

    /**
     * @notice Swaps PT to tokenOut via Pendle Router (before maturity).
     * @param pt The Principal Token address.
     * @param pendleMarket The Pendle market address for the swap.
     * @param ptBalance Amount of PT tokens to swap.
     * @param output Token output configuration from Pendle API.
     * @param limit Limit order fill data.
     * @return netTokenOut Amount of output tokens received.
     * @dev Output tokens are sent directly to msg.sender.
     *      Approves router, performs swap, then resets approval to zero.
     */
    function _swapPtToToken(
        address pt,
        address pendleMarket,
        uint256 ptBalance,
        TokenOutput calldata output,
        LimitOrderData calldata limit
    ) internal returns (uint256 netTokenOut) {
        IERC20(pt).forceApprove(PENDLE_ROUTER, ptBalance);

        (netTokenOut, , ) = IPAllActionV3(PENDLE_ROUTER).swapExactPtForToken(
            msg.sender, // tokens sent directly to user
            pendleMarket,
            ptBalance,
            output,
            limit
        );

        IERC20(pt).forceApprove(PENDLE_ROUTER, 0);
    }

    /**
     * @notice Redeems PT 1:1 to tokenOut via Pendle Router (post-maturity).
     * @param pt The Principal Token address to redeem.
     * @param yt The Yield Token address (required for redemption).
     * @param ptBalance Amount of PT tokens to redeem.
     * @param output Token output configuration from Pendle API.
     * @return netTokenOut Amount of output tokens received.
     * @dev Output tokens are sent directly to msg.sender.
     *      Approves router, performs redemption, then resets approval to zero.
     */
    function _redeemPtToToken(
        address pt,
        address yt,
        uint256 ptBalance,
        TokenOutput calldata output
    ) internal returns (uint256 netTokenOut) {
        IERC20(pt).forceApprove(PENDLE_ROUTER, ptBalance);

        (netTokenOut, ) = IPAllActionV3(PENDLE_ROUTER).redeemPyToToken(
            msg.sender, // tokenOut sent directly to user
            yt,
            ptBalance,
            output
        );

        IERC20(pt).forceApprove(PENDLE_ROUTER, 0);
    }

    /**
     * @notice Transfers only the dust accrued during the current transaction back to the recipient.
     * @param token The ERC-20 token address to sweep.
     * @param to The recipient address.
     * @param balanceBefore The adapter's token balance snapshot taken before operations began.
     * @dev Compares current balance against the pre-operation snapshot to sweep only the delta,
     *      preventing pre-existing balances from leaking to the caller.
     */
    function _sweepDust(address token, address to, uint256 balanceBefore) internal {
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (balance > balanceBefore) {
            IERC20(token).safeTransfer(to, balance - balanceBefore);
        }
    }

    /**
     * @notice Refunds only the native BNB dust accrued during the current transaction to the caller.
     * @param balanceBefore The adapter's native balance snapshot taken before operations began.
     */
    function _refundNativeDust(uint256 balanceBefore) internal {
        uint256 balance = address(this).balance;
        if (balance > balanceBefore) {
            Address.sendValue(payable(msg.sender), balance - balanceBefore);
        }
    }

    /**
     * @notice Validates that the market is registered.
     * @param pendleMarket The Pendle market address to validate.
     * @dev Reverts with MarketNotRegistered if PT address is zero.
     */
    function _requireRegisteredMarket(address pendleMarket) internal view {
        if (markets[pendleMarket].pt == address(0)) revert MarketNotRegistered(pendleMarket);
    }
}

